:root {
  --latar: #f4f6ef;
  --kartu: #ffffff;
  --teks: #1a1c18;
  --redup: #5a5f55;
  --utama: #2f6b3f;
  --galat: #b3261e;
  --sudut: 1rem;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.5;
  color: var(--teks);
  background: var(--latar);
}

.wadah { max-width: 36rem; margin: 0 auto; padding: 2rem 1rem; }
h1 { margin: 0 0 1.5rem; font-size: 1.75rem; }
h2 { margin: 0 0 0.75rem; font-size: 1.15rem; }

.cari { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0.5rem; }
.cari label { font-weight: 600; }
.cari-baris { display: flex; gap: 0.5rem; }

input, button { font: inherit; }

input {
  flex: 1;
  min-width: 0;
  padding: 0.7rem 0.9rem;
  border: 2px solid #8a8f86;
  border-radius: 0.75rem;
  background: var(--kartu);
}

button {
  padding: 0.7rem 1.1rem;
  border: 2px solid var(--utama);
  border-radius: 0.75rem;
  background: var(--utama);
  color: #fff;
  font-weight: 600;
  cursor: pointer;
}

.tombol-kedua { justify-self: start; background: transparent; color: var(--utama); }

button:disabled { opacity: 0.6; cursor: progress; }

input:focus-visible, button:focus-visible, a:focus-visible {
  outline: 3px solid var(--utama);
  outline-offset: 2px;
}

.status { min-height: 1.5em; margin: 1rem 0; color: var(--redup); }
.status[data-jenis="galat"] { color: var(--galat); font-weight: 600; }

.kartu {
  margin-bottom: 1rem;
  padding: 1.25rem;
  border-radius: var(--sudut);
  background: var(--kartu);
  box-shadow: 0 2px 10px rgb(0 0 0 / 0.06);
}

.kini-utama { display: flex; align-items: center; gap: 0.75rem; margin: 0; }
.ikon { font-size: 2.5rem; line-height: 1; }
.suhu { font-size: 3rem; font-weight: 700; }
.kini-label { margin: 0.25rem 0 1rem; font-size: 1.1rem; }

.detail { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.5rem; margin: 0; }
.detail dt { font-size: 0.85rem; color: var(--redup); }
.detail dd { margin: 0; font-weight: 600; }

.daftar-hari { margin: 0; padding: 0; list-style: none; }
.daftar-hari li {
  display: grid;
  grid-template-columns: 7.5rem 2rem 1fr auto;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 0;
  border-top: 1px solid #e6e9e1;
}
.daftar-hari li:first-child { border-top: 0; }
.daftar-hari .ikon { font-size: 1.5rem; }
.daftar-hari .suhu-hari { font-weight: 600; white-space: nowrap; }
.daftar-hari .hujan { grid-column: 3 / -1; font-size: 0.85rem; color: var(--redup); }

.kaki { padding: 1rem; text-align: center; font-size: 0.85rem; color: var(--redup); }
.kaki a { color: inherit; }

@media (max-width: 24rem) {
  .detail { grid-template-columns: 1fr 1fr; }
  .daftar-hari li { grid-template-columns: 1fr 2rem auto; }
  .daftar-hari .label, .daftar-hari .hujan { grid-column: 1 / -1; }
  .daftar-hari .suhu-hari { grid-row: 1; grid-column: 3; }
}

const URL_GEOCODING = "https://geocoding-api.open-meteo.com/v1/search";
const URL_PRAKIRAAN = "https://api.open-meteo.com/v1/forecast";

const form = document.querySelector("#form-cari");
const inputKota = document.querySelector("#input-kota");
const elStatus = document.querySelector("#status");
const kartuKini = document.querySelector("#cuaca-kini");

function tampilkanStatus(pesan, jenis = "info") {
  elStatus.textContent = pesan;
  elStatus.dataset.jenis = jenis;
}

function setSibuk(sibuk) {
  for (const el of form.elements) el.disabled = sibuk;
}

async function ambilJson(url) {
  let respons;
  try {
    respons = await fetch(url);
  } catch {
    throw new Error("Tidak bisa terhubung ke server cuaca. Periksa koneksi internetmu.");
  }
  if (!respons.ok) {
    throw new Error(`Server cuaca menolak permintaan (kode ${respons.status}). Coba lagi nanti.`);
  }
  return respons.json();
}

async function cariKota(nama) {
  const url = new URL(URL_GEOCODING);
  url.search = new URLSearchParams({ name: nama, count: 1, language: "id", format: "json" });
  const data = await ambilJson(url);
  // Kalau tidak ada hasil, Open-Meteo tidak mengirim properti "results" sama sekali.
  if (!data.results || data.results.length === 0) {
    throw new Error(`Kota "${nama}" tidak ditemukan. Periksa ejaannya, lalu coba lagi.`);
  }
  const kota = data.results[0];
  // Set membuang nama kembar, misalnya "Jakarta, Jakarta".
  const bagianNama = new Set([kota.name, kota.admin1, kota.country].filter(Boolean));
  return { nama: [...bagianNama].join(", "), lat: kota.latitude, lon: kota.longitude };
}

async function ambilCuaca(lat, lon) {
  const url = new URL(URL_PRAKIRAAN);
  url.search = new URLSearchParams({
    latitude: lat,
    longitude: lon,
    current: "temperature_2m,apparent_temperature,relative_humidity_2m,wind_speed_10m,weather_code,is_day",
    daily: "weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max",
    timezone: "auto",
    forecast_days: 7,
  });
  return ambilJson(url);
}

function tampilkanCuaca(namaTempat, kini) {
  document.querySelector("#judul-tempat").textContent = namaTempat;
  document.querySelector("#kini-suhu").textContent = `${Math.round(kini.temperature_2m)}°C`;
  // Sementara: tampilkan angka kodenya dulu. Labelnya dibuat di langkah berikutnya.
  document.querySelector("#kini-label").textContent = `Kode cuaca ${kini.weather_code}`;
  document.querySelector("#kini-terasa").textContent = `${Math.round(kini.apparent_temperature)}°C`;
  document.querySelector("#kini-lembap").textContent = `${kini.relative_humidity_2m}%`;
  document.querySelector("#kini-angin").textContent = `${Math.round(kini.wind_speed_10m)} km/jam`;
  kartuKini.hidden = false;
}

async function tampilkanUntuk(ambilTempat) {
  const fokus = document.activeElement; // elemen yang dinonaktifkan kehilangan fokus
  setSibuk(true);
  tampilkanStatus("Memuat cuaca...");
  try {
    const tempat = await ambilTempat();
    const data = await ambilCuaca(tempat.lat, tempat.lon);
    tampilkanCuaca(tempat.nama, data.current);
    tampilkanStatus(`Diperbarui pukul ${data.current.time.slice(11)} waktu setempat.`);
  } catch (galat) {
    console.error(galat);
    tampilkanStatus(galat.message, "galat");
  } finally {
    setSibuk(false);
    fokus.focus(); // kembalikan fokus untuk pengguna keyboard
  }
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  const nama = inputKota.value.trim();
  if (nama.length < 2) {
    tampilkanStatus("Ketik minimal 2 huruf nama kota.", "galat");
    inputKota.focus();
    return;
  }
  tampilkanUntuk(() => cariKota(nama));
});

