      elIkon,
      buatSpan("label", label),
      buatSpan("suhu-hari", `${Math.round(harian.temperature_2m_max[i])}° / ${Math.round(harian.temperature_2m_min[i])}°`),
      buatSpan("hujan", `Peluang hujan ${peluangHujan ?? "-"}%`),
    );
    return li;
  });
  daftarHari.replaceChildren(...baris);
  kartuPrakiraan.hidden = false;
}

