function mintaLokasi() {
  return new Promise((resolve, reject) => {
    if (!("geolocation" in navigator)) {
      reject(new Error("Browser-mu tidak mendukung fitur lokasi. Cari dengan nama kota saja."));
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (posisi) => resolve({ nama: "Lokasimu", lat: posisi.coords.latitude, lon: posisi.coords.longitude }),
      (galat) => {
        const pesan = galat.code === galat.PERMISSION_DENIED
          ? "Izin lokasi ditolak. Cari dengan nama kota saja."
          : "Lokasimu tidak bisa ditemukan. Coba lagi atau cari dengan nama kota.";
        reject(new Error(pesan));
      },
      { timeout: 10000, maximumAge: 10 * 60 * 1000 },
    );
  });
}

