function simpanTempat(tempat) {
  try {
    localStorage.setItem(KUNCI_SIMPAN, JSON.stringify(tempat));
  } catch {
    // Penyimpanan diblokir (misalnya mode privat): aplikasi tetap jalan tanpa mengingat.
  }
}

function bacaTempat() {
  try {
    const tempat = JSON.parse(localStorage.getItem(KUNCI_SIMPAN));
    return tempat && typeof tempat.lat === "number" && typeof tempat.lon === "number" ? tempat : null;
  } catch {
    return null;
  }
}

